module TopModule (
    input  logic       clk,
    input  logic       x,
    input  logic [2:0] y,
    output logic       Y0,
    output logic       z
);

  // Silence unused clock warning if any
  logic unused_clk;
  assign unused_clk = clk;

  logic [2:0] Y;

  always_comb begin
    Y = 3'b000;
    z = 1'b0;
    case (y)
      3'b000: begin
        if (x) Y = 3'b001;
        else   Y = 3'b000;
        z = 1'b0;
      end
      3'b001: begin
        if (x) Y = 3'b100;
        else   Y = 3'b001;
        z = 1'b0;
      end
      3'b010: begin
        if (x) Y = 3'b001;
        else   Y = 3'b010;
        z = 1'b0;
      end
      3'b011: begin
        if (x) Y = 3'b010;
        else   Y = 3'b001;
        z = 1'b1;
      end
      3'b100: begin
        if (x) Y = 3'b100;
        else   Y = 3'b011;
        z = 1'b1;
      end
      default: begin
        Y = 3'b000;
        z = 1'b0;
      end
    endcase
  end

  assign Y0 = Y[0];

endmodule

